for _code,(_why,_action) in EXTERNAL_RECOVERY.items():
    RULE_RECOVERY[_code]=('external',_why,_action)
for _code in NOT_IMPLEMENTED:
    RULE_RECOVERY[_code]=('external',f'Проверка «{RULE_TITLES[_code]}» не реализована или требует отдельного внешнего подтверждения.',
                         f'Получите отдельное подтверждение проверки «{RULE_TITLES[_code]}» у ответственного специалиста; этот отчёт его не заменяет.')
for _code,_title in PHASE_TITLES.items():
    RULE_RECOVERY[_code]=('export',f'Этап «{_title}» описывает выполнение указанной операции; завершение этапа не означает успех всех правил или нормативную готовность.',
                         'Откройте замечания соответствующих правил ниже; исправляйте конкретную причину по её observed/expected и инструкции, затем сформируйте новый вход.')


def rule_help(code):
    title = RULE_TITLES.get(code, PHASE_TITLES.get(code, 'Неизвестное правило проверки'))
    recovery=RULE_RECOVERY.get(code)
    if recovery is None:
        return dict(title=title, why='Для этого кода ещё нет проверенного пояснения.',
                    nextAction='Скачайте отчёт и передайте код проверки в поддержку. Исправление модели по этому коду не определено.', target='support')
    target,why,action=recovery
    return dict(title=title,why=why,nextAction=action,target=target)


