def error_help(code, status=500):
    group=next((key for key,items in ERROR_GROUPS.items() if code in items.split()), None)
    if group is None:
        group={401:'session',403:'session',404:'missing',408:'transfer',409:'refresh',410:'expired',413:'size',415:'input',422:'input',429:'quota',500:'service',503:'service',507:'quota'}.get(status,'input')
    title,why,action,retryable=ERROR_TEXT[group]
    return {'title':title,'why':why,'nextAction':action,'retryable':retryable,'category':group}
